cd /workspace && cat README.md && cat > src/service.ts <<'EOF'
import { Actor, Document } from './types';
import { DocumentRepository } from './repository';
export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    // Missing, deleted and foreign-tenant documents are indistinguishable to the caller.
    if (!document || document.deleted || document.tenant !== actor.tenant) throw new Error('not found');
    // Permission is enforced before the idempotency check, so a repeat by an
    // unauthorized actor still fails.
    if (!canArchive(actor, document)) throw new Error('forbidden');
    if (!document.archived) this.repository.archive(document, actor.user);
  }
}
function canArchive(actor: Actor, document: Document): boolean {
  switch (actor.role) {
    case 'admin': return true;
    case 'editor': return document.owner === actor.user;
    default: return false;
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

{
  const docs = () => [
    { id: 'own', tenant: 'a', owner: 'ed', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'gone', tenant: 'a', owner: 'ed', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'ed', deleted: false, archived: false },
    { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
  ];
  const admin = { tenant: 'a', user: 'ad', role: 'admin' };
  const editor = { tenant: 'a', user: 'ed', role: 'editor' };
  const viewer = { tenant: 'a', user: 'ed', role: 'viewer' };
  const fails = (actor, id, re) => {
    const r = new DocumentRepository(docs()); const s = new DocumentService(r);
    const before = JSON.stringify(r.documents);
    assert.throws(() => s.archive(actor, id), re);
    assert.equal(JSON.stringify(r.documents), before); assert.deepEqual(r.audit, []);
  };
  for (const a of [admin, editor, viewer]) for (const id of ['missing', 'gone', 'foreign']) fails(a, id, /^Error: not found$/);
  fails(editor, 'other', /^Error: forbidden$/);
  fails(viewer, 'own', /^Error: forbidden$/);
  fails(editor, 'done', /^Error: forbidden$/);
  fails(viewer, 'done', /^Error: forbidden$/);
  { const r = new DocumentRepository(docs()); const s = new DocumentService(r);
    s.archive(editor, 'own'); s.archive(editor, 'own');
    assert.equal(r.find('own').archived, true); assert.deepEqual(r.audit, [{ actor: 'ed', document: 'own' }]); }
  { const r = new DocumentRepository(docs()); const s = new DocumentService(r);
    s.archive(admin, 'other'); s.archive(admin, 'done');
    assert.deepEqual(r.audit, [{ actor: 'ad', document: 'other' }]); assert.equal(r.find('done').archived, true); }
}
console.log('public checks passed');
EOF
npx tsc -p tsconfig.json && node checks/public.cjs

